// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

contract Box {
    struct MainStorage {
        uint256 value;
        address owner;
    }

    MainStorage private main;

    function value() external view returns (uint256) {
        return main.value;
    }
}

