constants-and-immutables.source:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

contract Holder {
    uint256 public constant FIXED = 7;
    uint256 public immutable atDeploy;
    uint256 stored;

    constructor(uint256 given) {
        atDeploy = given;
    }

    function get() external view returns (uint256) {
        return stored + atDeploy;
    }
}

